import{_ as i,o as l,c as o,a6 as a,aq as c,ar as t}from"./chunks/framework.BfmC6wP_.js";const f=JSON.parse('{"title":"Content Security Policy (CSP) — Admin Tool Guide","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/design-system-wordpress-plugin/guide/SiteEditor/CSP.md","filePath":"content/plugins/design-system-wordpress-plugin/guide/SiteEditor/CSP.md"}'),s={name:"content/plugins/design-system-wordpress-plugin/guide/SiteEditor/CSP.md"};function r(n,e,d,p,m,u){return l(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="content-security-policy-csp-—-admin-tool-guide" tabindex="-1">Content Security Policy (CSP) — Admin Tool Guide <a class="header-anchor" href="#content-security-policy-csp-—-admin-tool-guide" aria-label="Permalink to “Content Security Policy (CSP) — Admin Tool Guide”">​</a></h1><p>Use this tool to control which sources your WordPress site can load for scripts, styles, images, fonts, media, XHR/WebSocket connections, and frames. Tight CSP rules improve security and reduce the risk of cross‑site scripting (XSS).</p><p>The tool lives in:</p><ul><li>WordPress Admin → Design System → Content Security Policy</li></ul><p>Click Save Settings to apply changes.</p><p><img src="'+c+'" alt="CSP Howto"></p><hr><h2 id="how-the-form-works" tabindex="-1">How the form works <a class="header-anchor" href="#how-the-form-works" aria-label="Permalink to “How the form works”">​</a></h2><ul><li>Each field accepts a space‑separated allowlist of sources (no commas).</li><li>If a field is left empty, the plugin uses its built‑in defaults (shown as helper text under each label).</li><li>You can add: <ul><li>Keywords: <code>&#39;self&#39;</code> <code>&#39;none&#39;</code> <code>&#39;unsafe-inline&#39;</code> <code>&#39;unsafe-eval&#39;</code> <code>data:</code> <code>blob:</code> <code>https:</code></li><li>Hosts: <code>example.com</code> <code>sub.example.com</code></li><li>Wildcards: <code>*.example.com</code></li></ul></li><li>Use the least‑privilege set you can. Prefer HTTPS. Avoid <code>&#39;unsafe-inline&#39;</code> and <code>&#39;unsafe-eval&#39;</code> when possible.</li></ul><p>Tip: To revert a directive to defaults, clear the field and Save Settings. To block a type entirely, enter <code>&#39;none&#39;</code>.</p><hr><h2 id="directive-reference" tabindex="-1">Directive reference <a class="header-anchor" href="#directive-reference" aria-label="Permalink to “Directive reference”">​</a></h2><p>Below is what each field controls and examples of what you might add. The defaults shown in the UI include the design system’s domains (e.g., gov.bc.ca, twimg.com, flickr domains, and YouTube for embeds).</p><h3 id="default-src-policy" tabindex="-1">Default-src Policy <a class="header-anchor" href="#default-src-policy" aria-label="Permalink to “Default-src Policy”">​</a></h3><ul><li>Fallback for all resource types without an explicit directive.</li><li>Keep minimal. Add broad hosts here only if you can’t scope them to a more specific directive.</li></ul><p>Example additions:</p><ul><li><code>https: cdn.example.com</code></li></ul><h3 id="script-src-policy" tabindex="-1">Script-src Policy <a class="header-anchor" href="#script-src-policy" aria-label="Permalink to “Script-src Policy”">​</a></h3><ul><li>JavaScript files and inline JS.</li><li>Prefer hosted files over inline scripts. Remove &#39;unsafe-inline&#39;/&#39;unsafe-eval&#39; if your site doesn’t require them.</li></ul><p>Example additions:</p><ul><li><code>cdn.jsdelivr.net cdn.skypack.dev www.googletagmanager.com www.google-analytics.com</code></li></ul><h3 id="style-src-policy" tabindex="-1">Style-src Policy <a class="header-anchor" href="#style-src-policy" aria-label="Permalink to “Style-src Policy”">​</a></h3><ul><li>CSS files and inline styles.</li><li>If you must allow inline styles, keep &#39;unsafe-inline&#39;. Consider using hashed inline styles instead of broad allowance.</li></ul><p>Example additions:</p><ul><li><code>fonts.googleapis.com cdn.jsdelivr.net</code></li></ul><h3 id="connect-src-policy" tabindex="-1">Connect-src Policy <a class="header-anchor" href="#connect-src-policy" aria-label="Permalink to “Connect-src Policy”">​</a></h3><ul><li>Fetch/XHR, WebSocket, EventSource, analytics beacons, and GraphQL endpoints.</li></ul><p>Example additions:</p><ul><li><code>api.example.com *.sentry.io</code></li></ul><h3 id="img-src-policy" tabindex="-1">Img-src Policy <a class="header-anchor" href="#img-src-policy" aria-label="Permalink to “Img-src Policy”">​</a></h3><ul><li>Images and favicons. data: allows inline base64 images.</li></ul><p>Example additions:</p><ul><li><code>i.ytimg.com cdn.example.com data:</code></li></ul><h3 id="font-src-policy" tabindex="-1">Font-src Policy <a class="header-anchor" href="#font-src-policy" aria-label="Permalink to “Font-src Policy”">​</a></h3><ul><li>Font files (woff, woff2, ttf). data: enables embedded fonts like <code>data:font/woff2;base64,d09GMgABAAAAAA...&#39;)</code></li></ul><p>Example additions:</p><ul><li><code>fonts.gstatic.com data:</code></li></ul><h3 id="media-src-policy" tabindex="-1">Media-src Policy <a class="header-anchor" href="#media-src-policy" aria-label="Permalink to “Media-src Policy”">​</a></h3><ul><li>Audio and video files (not iframes).</li></ul><p>Example additions:</p><ul><li><code>media.example.com</code></li></ul><h3 id="frame-src-policy" tabindex="-1">Frame-src Policy <a class="header-anchor" href="#frame-src-policy" aria-label="Permalink to “Frame-src Policy”">​</a></h3><ul><li>Origins allowed in iframes (and workers for some browsers).</li></ul><p>Example additions:</p><ul><li><code>*.youtube.com youtu.be *.vimeo.com *.rumble.com</code></li></ul><hr><h2 id="common-recipes" tabindex="-1">Common recipes <a class="header-anchor" href="#common-recipes" aria-label="Permalink to “Common recipes”">​</a></h2><ul><li><p>Google Fonts</p><ul><li>style-src: <code>fonts.googleapis.com</code></li><li>font-src: <code>fonts.gstatic.com data</code>:</li></ul></li><li><p>YouTube/Vimeo embeds</p><ul><li>frame-src: <code>*.youtube.com youtu.be *.vimeo.com</code></li><li>img-src: <code>i.ytimg.com</code> (for thumbnails)</li></ul></li><li><p>Mapbox</p><ul><li>script-src: <code>api.mapbox.com</code></li><li>style-src: <code>api.mapbox.com</code></li><li>img-src: <code>api.mapbox.com</code></li><li>connect-src: <code>events.mapbox.com</code></li></ul></li><li><p>Generic CDN</p><ul><li>Add the CDN host to the specific directive you need (script-src, style-src, img-src, etc.), e.g., <code>cdn.example.com</code></li></ul></li></ul><hr><h2 id="testing-changes" tabindex="-1">Testing changes <a class="header-anchor" href="#testing-changes" aria-label="Permalink to “Testing changes”">​</a></h2><ol><li>Save Settings.</li><li>Hard‑refresh the page in your browser (Shift+Reload).</li><li>Open DevTools → Console. Look for “Refused to connect/script/style from … because it violates the Content Security Policy”.</li><li>Add the blocked origin to the correct directive and save again.</li><li>Repeat until violations are gone.</li></ol><p>Tip: If something still doesn’t load, verify the exact hostname in the violation message and add that host (or a wildcard like *.example.com) to the correct directive.</p><p><img src="'+t+'" alt="CSP Frame Source"></p><hr><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><ul><li><p>How do I reset to defaults?</p><ul><li>Clear the field and click Save Settings.</li></ul></li><li><p>Can I disable a resource type completely?</p><ul><li>Enter &#39;none&#39; in that directive and save.</li></ul></li><li><p>Do I need commas?</p><ul><li>No. Use spaces between entries.</li></ul></li></ul>',56)])])}const y=i(s,[["render",r]]);export{f as __pageData,y as default};
